        <div class="home-content-grid"><section class="home-card surface"><header class="home-section-head section-header"><div class="section-header-main"><span class="section-header-eyebrow">UPCOMING</span><h3 class="section-header-title">Your theatre timeline</h3></div><a href="<?=$u('/calendar')?>">Full calendar</a></header><?php if($timeline):foreach(array_slice($timeline,0,7) as $item):?><article class="home-timeline-row<?=!empty($item['has_conflict'])?' conflict':''?>"><time><b><?=$e(date('M j',strtotime((string)$item['starts_at'])))?></b><span><?=$e(date('g:i A',strtotime((string)$item['starts_at'])))?></span></time><i><?=$e((string)$item['subject_initials'])?></i><div><b><?=$e((string)$item['title'])?></b><span><?=$e((string)$item['subject_name'])?> · <?=$e((string)$item['production_title'])?></span><small><?=$e((string)$item['location'])?><?=!empty($item['group_names'])?' · '.$e(implode(' + ',$item['group_names'])):''?></small></div><?=!empty($item['has_conflict'])?'<em>Conflict</em>':''?></article><?php endforeach;else:?><div class="home-empty empty-state empty-state-compact"><b>No upcoming production activity.</b><span>Your account-wide schedule will build itself as memberships are assigned.</span></div><?php endif;?></section>

        <?php $unreadNotes=array_values(array_filter($notes,static fn(array $n):bool=>empty($n['read_at'])));$readNotes=array_values(array_filter($notes,static fn(array $n):bool=>!empty($n['read_at']))); ?>
