        <?php if($unreadNotes):foreach($unreadNotes as $note):?><a class="home-notice<?=$note['read_at']===null?' unread':''?>" href="<?=$u($note['source_type']==='casting_offer_response'?'/production/casting':($note['source_type']==='casting_offer' && (int)$note['source_id']>0?'/notifications?offer='.(int)$note['source_id'].'#casting-offer-'.(int)$note['source_id']:(string)($note['action_path']?:'/notifications')))?>"><small><?=$note['read_at']===null?'NEW · ':''?><?=$e(strtoupper(str_replace('_',' ',(string)$note['source_type'])))?></small><b><?=$e((string)$note['title'])?></b><p><?=$e((string)$note['body'])?></p><span><?=$e(date('M j · g:i A',strtotime((string)$note['created_at'])))?><?=$note['source_type']==='casting_offer'?' · Review offer →':''?></span></a><?php endforeach;else:?><div class="home-empty"><b>All caught up.</b><span>No unread updates right now.</span></div><?php endif;?>
        <?php if($readNotes):?><details class="notification-history home-notification-history"><summary>Past notifications <span><?=count($readNotes)?></span></summary><div class="notification-history-items"><?php foreach(array_slice($readNotes,0,10) as $note):?><a class="home-notice<?=$note['read_at']===null?' unread':''?>" href="<?=$u($note['source_type']==='casting_offer' && (int)$note['source_id']>0?'/notifications?offer='.(int)$note['source_id'].'#casting-offer-'.(int)$note['source_id']:(string)($note['action_path']?:'/notifications'))?>"><small><?=$note['read_at']===null?'NEW · ':''?><?=$e(strtoupper(str_replace('_',' ',(string)$note['source_type'])))?></small><b><?=$e((string)$note['title'])?></b><p><?=$e((string)$note['body'])?></p><span><?=$e(date('M j · g:i A',strtotime((string)$note['created_at'])))?><?=$note['source_type']==='casting_offer'?' · Review offer →':''?></span></a><?php endforeach; ?></div><?php if(count($readNotes)>10):?><a class="notification-history-more" href="<?=$u('/notifications')?>">View all past notifications →</a><?php endif;?></details><?php endif;?></section>

        <section class="home-card"><header class="home-section-head"><div><span>YOUR THEATRE</span><h3>People & productions</h3></div><?php if($children):?><a href="<?=$u('/family-hub')?>">Family</a><?php endif;?></header><?php if($productions):foreach($productions as $production):?><article class="home-production"><span>★</span><div><b><?=$e((string)$production['title'])?></b><small><?=$e((string)($production['season']?:'Active production'))?></small></div></article><?php endforeach;endif;?><?php if($children):foreach(array_slice($children,0,4) as $child):?><article class="home-person"><i><?=$e((string)$child['initials'])?></i><div><b><?=$e((string)$child['name'])?></b><span><?=count($child['productions'])?> active production<?=count($child['productions'])===1?'':'s'?></span></div><a href="<?=$u('/family-hub')?>">View</a></article><?php endforeach;endif;?><?php if(!$productions&&!$children):?><div class="home-empty"><b>Your theatre connections will appear here.</b><span>No production or child relationship is attached to this account yet.</span></div><?php endif;?></section></aside></div>

        <?php if($membership['approved'] || $productions):?>
        <section class="home-card ux-connect"><header class="home-section-head"><h3>Stay connected</h3></header><p>Open the conversations and production updates available to your account.</p><div class="ux-link-row"><a href="<?=$u('/messages')?>">Messages →</a><a href="<?=$u('/channels')?>">Community →</a><a href="<?=$u('/cast')?>">Casting announcements →</a></div></section>
        <?php endif;?>
        <?php if($volunteer):?><section class="home-card home-volunteer"><header class="home-section-head"><div><span>VOLUNTEER</span><h3>Your upcoming commitments</h3></div><a href="<?=$u('/volunteer-shifts')?>">Volunteer hub</a></header><div class="home-volunteer-grid"><?php foreach(array_slice($volunteer,0,4) as $shift):?><article><small><?=$e(strtoupper(str_replace('_',' ',(string)$shift['status'])))?></small><b><?=$e((string)$shift['title'])?></b><span><?=$e(date('M j · g:i A',strtotime((string)$shift['starts_at'])))?> · <?=$e((string)$shift['location'])?></span><?php if($shift['production_title']):?><em><?=$e((string)$shift['production_title'])?></em><?php endif;?></article><?php endforeach;?></div></section><?php endif;?>

        </div></main></div><script src="<?=$u('/assets/js/unified-navigation.js')?>"></script></body></html><?php exit;
